import {
  createForks,
  teardownForks,
  createWorkspace,
  teardownWorkspace,
  type Forks,
  type Workspace,
  type TigrisAgentKitConfig,
} from "@tigrisdata/agent-kit";
import {
  S3Client,
  GetObjectCommand,
  PutObjectCommand,
  ListObjectsV2Command,
  CreateBucketCommand,
  DeleteBucketCommand,
  DeleteObjectCommand,
} from "@aws-sdk/client-s3";
import { getBucketInfo } from "@tigrisdata/storage";
import { writeFileSync } from "fs";

const TIGRIS_ENDPOINT = "REDACTED";
const TIGRIS_REGION = "REDACTED";
const GOLD_BUCKET = "gold-eval-dataset";
const FORK_PREFIX = "eval-attempt";
const NUM_FORKS = 3;

/** Build a TigrisAgentKitConfig using the provided credentials (or env vars). */
function agentKitConfig(creds?: {
  accessKeyId: string;
  secretAccessKey: string;
}): TigrisAgentKitConfig {
  return {
    endpoint: TIGRIS_ENDPOINT,
    accessKeyId: creds?.accessKeyId ?? process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
    secretAccessKey:
      creds?.secretAccessKey ?? process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
  };
}

/** Build an S3Client scoped to a specific set of credentials. */
function makeS3Client(creds?: {
  accessKeyId: string;
  secretAccessKey: string;
}): S3Client {
  return new S3Client({
    region: TIGRIS_REGION,
    endpoint: TIGRIS_ENDPOINT,
    credentials: {
      accessKeyId:
        creds?.accessKeyId ?? process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey:
        creds?.secretAccessKey ??
        process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });
}

/** Read an S3 object body as a UTF-8 string. */
async function getObjectText(
  s3: S3Client,
  bucket: string,
  key: string
): Promise<string> {
  const res = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
  if (!res.Body) throw new Error(`Empty body for s3://${bucket}/${key}`);
  return res.Body.transformToString("utf-8");
}

/** List all keys under a prefix in a bucket. */
async function listKeys(
  s3: S3Client,
  bucket: string,
  prefix: string
): Promise<string[]> {
  const keys: string[] = [];
  let continuationToken: string | undefined;
  do {
    const res = await s3.send(
      new ListObjectsV2Command({
        Bucket: bucket,
        Prefix: prefix,
        ContinuationToken: continuationToken,
      })
    );
    for (const obj of res.Contents ?? []) {
      if (obj.Key) keys.push(obj.Key);
    }
    continuationToken = res.IsTruncated ? res.NextContinuationToken : undefined;
  } while (continuationToken);
  return keys;
}

/**
 * Ensure the gold bucket has snapshot support enabled at the storage level.
 * If the bucket was created without the X-Tigris-Enable-Snapshot header, forks
 * will fail with "Source bucket must be of snapshot type".
 * We fix this by: (1) reading all existing objects, (2) deleting the bucket,
 * (3) re-creating it with the snapshot header, (4) re-uploading all objects.
 */
async function ensureSnapshotEnabled(adminS3: S3Client): Promise<void> {
  const config = agentKitConfig();

  // Check if snapshot is already enabled (S3-level type, not just the MGMT flag)
  // We detect this by trying to create a test fork; instead, use getBucketInfo
  // from @tigrisdata/storage which reads the raw `type` field.
  const info = await getBucketInfo(GOLD_BUCKET, { config });
  if (info.data?.isSnapshotEnabled) {
    // Verify it works by attempting a CreateBucket with fork headers on a dummy name
    // to detect the "must be of snapshot type" edge case.
    // Rather than doing an extra round-trip, trust the API flag if it's true from a
    // freshly-created (with header) bucket — but if we got here after a type:1 PATCH
    // only, the S3-level check may still fail.  The safest approach: always try a
    // snapshot and a test fork to confirm.
    console.log(
      `[preflight] ${GOLD_BUCKET} reports isSnapshotEnabled=true; verifying fork compatibility…`
    );
  }

  // Read all existing objects from the gold bucket before any modification.
  const existingKeys = await listKeys(adminS3, GOLD_BUCKET, "");
  const objects: Array<{ key: string; body: Uint8Array; contentType: string }> =
    [];

  for (const key of existingKeys) {
    const res = await adminS3.send(
      new GetObjectCommand({ Bucket: GOLD_BUCKET, Key: key })
    );
    if (!res.Body) throw new Error(`Empty body for ${key}`);
    const bytes = await res.Body.transformToByteArray();
    objects.push({ key, body: bytes, contentType: res.ContentType ?? "application/octet-stream" });
  }
  console.log(
    `[preflight] Read ${objects.length} object(s) from ${GOLD_BUCKET}: ${objects.map((o) => o.key).join(", ")}`
  );

  // Delete all objects then the bucket.
  for (const obj of objects) {
    await adminS3.send(
      new DeleteObjectCommand({ Bucket: GOLD_BUCKET, Key: obj.key })
    );
  }
  await adminS3.send(new DeleteBucketCommand({ Bucket: GOLD_BUCKET }));
  console.log(`[preflight] Deleted ${GOLD_BUCKET}`);

  // Re-create with snapshot enabled.
  const createCmd = new CreateBucketCommand({ Bucket: GOLD_BUCKET });
  createCmd.middlewareStack.add(
    (next) => async (args) => {
      (args.request as { headers: Record<string, string> }).headers[
        "X-Tigris-Enable-Snapshot"
      ] = "true";
      return next(args);
    },
    { step: "build" }
  );
  await adminS3.send(createCmd);
  console.log(`[preflight] Re-created ${GOLD_BUCKET} with snapshot enabled`);

  // Re-upload all objects.
  for (const obj of objects) {
    await adminS3.send(
      new PutObjectCommand({
        Bucket: GOLD_BUCKET,
        Key: obj.key,
        Body: obj.body,
        ContentType: obj.contentType,
      })
    );
  }
  console.log(
    `[preflight] Re-uploaded ${objects.length} object(s) to ${GOLD_BUCKET}`
  );
}

/** Process one fork: create a writer workspace, reverse all prompt answers, return aggregated data. */
async function processFork(
  forkIndex: number,
  forkBucket: string,
  forkCreds: { accessKeyId: string; secretAccessKey: string },
  adminConfig: TigrisAgentKitConfig
): Promise<{
  workspace: Workspace;
  answers: Record<string, string>;
}> {
  const writerName = `eval-writer-${forkIndex}`;
  console.log(`[fork ${forkIndex}] Creating writer workspace "${writerName}"…`);

  const wsResult = await createWorkspace(writerName, {
    credentials: { role: "Editor" },
    config: adminConfig,
  });
  if (wsResult.error) {
    throw new Error(
      `Failed to create workspace "${writerName}": ${wsResult.error.message}`
    );
  }
  const workspace = wsResult.data;
  console.log(`[fork ${forkIndex}] Writer workspace "${writerName}" created.`);

  // S3 clients scoped to their respective credentials
  const forkS3 = makeS3Client(forkCreds);
  const writerS3 = makeS3Client(workspace.credentials);

  // List prompt keys from the read-only fork
  const promptKeys = await listKeys(forkS3, forkBucket, "prompts/");
  console.log(
    `[fork ${forkIndex}] Found ${promptKeys.length} prompt(s): ${promptKeys.join(", ")}`
  );

  const answers: Record<string, string> = {};

  for (const key of promptKeys) {
    // key looks like "prompts/p1.json"
    const filename = key.split("/").pop()!; // "p1.json"
    const promptName = filename.replace(".json", ""); // "p1"

    const content = await getObjectText(forkS3, forkBucket, key);
    const reversed = content.split("").reverse().join("");
    const answerKey = `answers/${promptName}.txt`;

    await writerS3.send(
      new PutObjectCommand({
        Bucket: workspace.bucket,
        Key: answerKey,
        Body: reversed,
        ContentType: "text/plain",
      })
    );
    console.log(
      `[fork ${forkIndex}] Wrote reversed answer to ${workspace.bucket}/${answerKey}`
    );
    answers[promptName] = reversed;
  }

  return { workspace, answers };
}

async function main() {
  const adminConfig = agentKitConfig();
  const adminS3 = makeS3Client();

  let forksResult: Forks | null = null;
  const workspaces: Workspace[] = [];

  try {
    // ── Pre-flight: ensure the gold bucket supports snapshots/forking ──────────
    await ensureSnapshotEnabled(adminS3);

    // ── Step 1: Fork the gold dataset into 3 isolated read-only environments ──
    console.log(
      `Creating ${NUM_FORKS} forks of "${GOLD_BUCKET}" with prefix "${FORK_PREFIX}"…`
    );
    const forksResponse = await createForks(GOLD_BUCKET, NUM_FORKS, {
      prefix: FORK_PREFIX,
      credentials: { role: "ReadOnly" },
      config: adminConfig,
    });
    if (forksResponse.error) {
      throw new Error(`createForks failed: ${forksResponse.error.message}`);
    }
    forksResult = forksResponse.data;
    console.log(
      `Forks created: ${forksResult.forks.map((f) => f.bucket).join(", ")}`
    );

    if (forksResult.forks.length !== NUM_FORKS) {
      throw new Error(
        `Expected ${NUM_FORKS} forks but got ${forksResult.forks.length}`
      );
    }

    // ── Step 2: Process all forks in parallel ──
    const forkTasks = forksResult.forks.map((fork, idx) => {
      if (!fork.credentials) {
        throw new Error(`Fork ${idx} has no credentials`);
      }
      return processFork(idx, fork.bucket, fork.credentials, adminConfig);
    });

    const results = await Promise.all(forkTasks);

    // Collect workspaces for teardown
    for (const r of results) {
      workspaces.push(r.workspace);
    }

    // ── Step 3: Fetch answers back and aggregate ──
    console.log("Aggregating answers from writer workspaces…");
    const aggregated: Record<string, Record<string, string>> = {};

    for (let i = 0; i < forksResult.forks.length; i++) {
      const forkBucket = forksResult.forks[i].bucket; // e.g. "eval-attempt-0"
      const workspace = results[i].workspace;
      const writerS3 = makeS3Client(workspace.credentials);

      const answerKeys = await listKeys(writerS3, workspace.bucket, "answers/");
      const bucketAnswers: Record<string, string> = {};

      for (const key of answerKeys) {
        // key looks like "answers/p1.txt"
        const filename = key.split("/").pop()!; // "p1.txt"
        const promptName = filename.replace(".txt", ""); // "p1"
        const content = await getObjectText(writerS3, workspace.bucket, key);
        bucketAnswers[promptName] = content;
      }

      aggregated[forkBucket] = bucketAnswers;
    }

    const outputPath = "/home/user/orchestrator/aggregated.json";
    writeFileSync(outputPath, JSON.stringify(aggregated, null, 2), "utf-8");
    console.log(`Aggregated results written to ${outputPath}`);
    console.log(JSON.stringify(aggregated, null, 2));
  } finally {
    // ── Step 4: Tear down all resources ──
    console.log("Tearing down writer workspaces…");
    for (const ws of workspaces) {
      const res = await teardownWorkspace(ws, { config: adminConfig });
      if (res.error) {
        console.error(
          `Warning: teardownWorkspace("${ws.bucket}") failed: ${res.error.message}`
        );
      } else {
        console.log(`Workspace "${ws.bucket}" torn down.`);
      }
    }

    if (forksResult) {
      console.log("Tearing down forks…");
      const res = await teardownForks(forksResult, { config: adminConfig });
      if (res.error) {
        console.error(`Warning: teardownForks failed: ${res.error.message}`);
      } else {
        console.log("All forks torn down.");
      }
    }
  }

  console.log("Done. Exiting with status 0.");
  process.exit(0);
}

main().catch((err) => {
  console.error("Fatal error:", err instanceof Error ? err.stack : err);
  process.exit(1);
});

